BEGIN;
-- Staging only. All entities, observation text, employment and credential evidence below are synthetic.
-- Exercises SQL contracts under synthetic JWT/session claims, not Auth HTTP, Storage bytes or real clinical acceptance.
-- The private review scope is privileged fixture setup only. It grants no real qualification.
DO $fixture$
DECLARE
 fx_t uuid:=gen_random_uuid();fx_u uuid:=gen_random_uuid();fx_s uuid:=gen_random_uuid();fx_r uuid:=gen_random_uuid();fx_empty_role uuid:=gen_random_uuid();fx_c uuid:=gen_random_uuid();fx_other_c uuid:=gen_random_uuid();
 fx_reviewer uuid:=gen_random_uuid();fx_review_s uuid:=gen_random_uuid();fx_review_r uuid:=gen_random_uuid();fx_order uuid:=gen_random_uuid();fx_wound uuid;fx_assessment uuid;fx_plan uuid;fx_dressing uuid;fx_lifecycle uuid;fx_correction uuid;
 fx_create_req uuid:=gen_random_uuid();fx_assess_req uuid:=gen_random_uuid();fx_plan_req uuid:=gen_random_uuid();fx_dress_req uuid:=gen_random_uuid();fx_path_req uuid:=gen_random_uuid();fx_revise_req uuid:=gen_random_uuid();fx_review_req uuid:=gen_random_uuid();fx_decision_req uuid:=gen_random_uuid();
 fx_employee uuid:=gen_random_uuid();fx_document uuid:=gen_random_uuid();fx_qualification uuid:=gen_random_uuid();fx_scope uuid:=gen_random_uuid();
 fx_base timestamptz:=date_trunc('minute',clock_timestamp())-interval '1 day';fx_claims jsonb;fx_review_claims jsonb;fx_create jsonb;fx_assess jsonb;fx_plan_data jsonb;fx_dress_data jsonb;fx_lifecycle_data jsonb;fx_correction_data jsonb;
 fx_create_payload jsonb;fx_assess_payload jsonb;fx_plan_payload jsonb;fx_dress_payload jsonb;fx_lifecycle_payload jsonb;
 fx_order_before jsonb;fx_case_before jsonb;fx_assess_before jsonb;fx_case_row jsonb;fx_context jsonb;fx_entry jsonb;fx_closed_entry jsonb;fx_packet jsonb;fx_packet2 jsonb;fx_receipt jsonb;fx_receipt2 jsonb;fx_review_packet jsonb;fx_review_receipt jsonb;fx_decision_packet jsonb;fx_decision_receipt jsonb;fx_page jsonb;fx_next jsonb;
 fx_bad jsonb;fx_result uuid;fx_count bigint;fx_error text;fx_passed boolean:=false;
BEGIN
 BEGIN
  INSERT INTO public.tenants(id,name) VALUES(fx_t,'CP365 isolated synthetic Wound fixture');
  INSERT INTO public.roles(id,key,name) VALUES(fx_r,'cp365_wound_'||fx_r,'Synthetic wound documenter'),(fx_empty_role,'cp365_empty_'||fx_empty_role,'Synthetic empty role'),(fx_review_r,'cp365_review_'||fx_review_r,'Synthetic wound reviewer');
  INSERT INTO public.role_permissions(role_id,permission_key) SELECT fx_r,unnest(ARRAY['pflege.wounds.view','pflege.wounds.manage','pflege.orders.view','pflege.treatment.view','pflege.treatment.manage','pflege.documentation.sign']);
  INSERT INTO public.role_permissions(role_id,permission_key) SELECT fx_review_r,unnest(ARRAY['pflege.wounds.view','pflege.orders.view','pflege.treatment.view','pflege.documentation.sign']);
  INSERT INTO auth.users(id,email,raw_user_meta_data,raw_app_meta_data) VALUES(fx_u,fx_u||'@example.invalid','{}','{}'),(fx_reviewer,fx_reviewer||'@example.invalid','{}','{}');
  UPDATE public.profiles SET tenant_id=fx_t,role_id=fx_r,role_key='pfleger',is_active=true,status='active',display_name='Synthetic Wound Documenter' WHERE id=fx_u;
  UPDATE public.profiles SET tenant_id=fx_t,role_id=fx_review_r,role_key='pfleger',is_active=true,status='active',display_name='Synthetic Independent Reviewer' WHERE id=fx_reviewer;
  INSERT INTO auth.sessions(id,user_id,not_after) VALUES(fx_s,fx_u,clock_timestamp()+interval '2 hours'),(fx_review_s,fx_reviewer,clock_timestamp()+interval '2 hours');
  INSERT INTO public.clients(id,tenant_id,first_name,last_name,status) VALUES(fx_c,fx_t,'Synthetic','Wound','aktiv'),(fx_other_c,fx_t,'Synthetic','Other case','aktiv');
  INSERT INTO public.client_module_assignments(tenant_id,client_id,module_key,status,is_active) VALUES(fx_t,fx_c,'pflege','active',true),(fx_t,fx_other_c,'pflege','active',true);
  fx_claims:=jsonb_build_object('sub',fx_u,'role','authenticated','session_id',fx_s,'exp',extract(epoch from clock_timestamp()+interval '1 hour')::bigint);
  fx_review_claims:=jsonb_build_object('sub',fx_reviewer,'role','authenticated','session_id',fx_review_s,'exp',extract(epoch from clock_timestamp()+interval '1 hour')::bigint);
  PERFORM set_config('request.jwt.claims',fx_claims::text,true);

  fx_create:=jsonb_build_object('bodyLocation','Synthetisch dokumentierter linker Unterarm','side','left','woundType','Synthetischer Wundtyp','etiology','Fiktiver Befund ohne klinische Schlussfolgerung','onsetDate','','onsetUnknownReason','Entstehung im synthetischen Test unbekannt','acquiredWhere','Synthetische häusliche Umgebung','description','Isolierter technischer Testfall ohne reale betroffene Person','basisStatus','pending','basisReference','Ärztliche Grundlage im Test ausdrücklich offen','physician','','carePlan','Keine vorab ausgeführte Versorgung','nextReviewAt','','reviewStatus','pending','reviewPendingReason','Synthetische Terminabstimmung noch offen');
  fx_create_payload:=jsonb_build_object('action','create','subjectId',fx_c,'dataJson',fx_create::text);
  fx_wound:=care_private.write_wound_documentation(fx_create_req,fx_create_payload);
  SELECT to_jsonb(w) INTO fx_case_before FROM public.clinical_wound_cases w WHERE w.id=fx_wound;
  IF fx_case_before->>'status' IS DISTINCT FROM 'draft' OR fx_case_before->>'physician_involved' IS DISTINCT FROM 'false' OR fx_case_before->'onset_date' IS DISTINCT FROM 'null'::jsonb OR EXISTS(SELECT 1 FROM public.clinical_wound_assessments a WHERE a.wound_case_id=fx_wound) THEN RAISE EXCEPTION 'Case creation invented clinical facts or initial assessment';END IF;
  IF care_private.write_wound_documentation(fx_create_req,fx_create_payload) IS DISTINCT FROM fx_wound THEN RAISE EXCEPTION 'Case exact retry did not return original';END IF;
  BEGIN PERFORM care_private.write_wound_documentation(fx_create_req,jsonb_set(fx_create_payload,'{subjectId}',to_jsonb(fx_other_c)));RAISE EXCEPTION 'Request reused for another case';EXCEPTION WHEN check_violation THEN NULL;END;
  BEGIN UPDATE public.client_module_assignments SET is_active=false WHERE tenant_id=fx_t AND client_id=fx_c AND module_key='pflege';PERFORM care_private.write_wound_documentation(gen_random_uuid(),fx_create_payload);RAISE EXCEPTION 'Inactive assignment accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;

  fx_assess:=jsonb_build_object('observedAt',to_char((fx_base+interval '1 minute 0.123 second') at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'measurementMethod','Fiktive dokumentierte Messmethode','lengthState','measured','lengthCm','1.25','lengthReason','','widthState','not_measurable','widthCm','','widthReason','Im synthetischen Test nicht messbar','depthState','not_measurable','depthCm','','depthReason','Im synthetischen Test nicht messbar','woundBed','Synthetische Beschreibung des Wundgrunds','exudate','Synthetisch beobachtete Exsudation','odor','Synthetisch beobachteter Geruch','woundEdge','Synthetisch beschriebener Wundrand','surroundingSkin','Synthetisch beschriebene Umgebung','painState','not_assessable','painScore','','painReason','Im Test nicht erhoben; kein erfundener Nullwert','infectionObservation','Synthetische Beobachtung ohne Diagnose','personalImpact','Synthetisch dokumentierte Auswirkung','preferences','Fiktive Präferenz ausdrücklich erfragt','selfManagement','Fiktiver Unterstützungsbedarf','actualAction','Nur synthetische Beobachtung dokumentiert','response','Keine klinische Freigabe aus diesem Test','nextReviewAt','','reviewStatus','pending','reviewPendingReason','Kontrolle im Test noch abzustimmen');
  fx_assess_payload:=jsonb_build_object('action','assessment','subjectId',fx_wound,'dataJson',fx_assess::text);
  fx_assessment:=care_private.write_wound_documentation(fx_assess_req,fx_assess_payload);
  SELECT to_jsonb(a) INTO fx_assess_before FROM public.clinical_wound_assessments a WHERE a.id=fx_assessment;
  IF fx_assess_before->>'length_cm' IS DISTINCT FROM '1.25' OR fx_assess_before->'width_cm' IS DISTINCT FROM 'null'::jsonb OR fx_assess_before->'depth_cm' IS DISTINCT FROM 'null'::jsonb OR fx_assess_before->'pain_score' IS DISTINCT FROM 'null'::jsonb OR fx_assess_before->>'observed_at' IS NULL THEN RAISE EXCEPTION 'Unknown assessment facts were filled or observation missing';END IF;
  IF care_private.write_wound_documentation(fx_assess_req,fx_assess_payload) IS DISTINCT FROM fx_assessment THEN RAISE EXCEPTION 'Assessment exact retry changed result';END IF;
  BEGIN UPDATE public.clinical_wound_assessments SET pain_score=0 WHERE id=fx_assessment;RAISE EXCEPTION 'Prepared assessment original mutable';EXCEPTION WHEN insufficient_privilege THEN NULL;END;

  INSERT INTO public.care_medical_orders(id,tenant_id,client_id,order_type,title,description,ordering_physician,ordered_at,valid_from,valid_until,insurer_approval_required,insurer_approval_status,qualification_requirement,source_document,recorded_by,recorded_by_name)
  VALUES(fx_order,fx_t,fx_c,'wound_dressing','Synthetische Anordnung','Nur synthetischer Originalvertrag für SQLprüfung','Synthetisch benannte verordnende Person',(fx_base at time zone 'Europe/Berlin')::date,(fx_base at time zone 'Europe/Berlin')::date,((fx_base at time zone 'Europe/Berlin')::date+30),true,'pending','Keine tatsächliche Qualifikation durch Test bestätigt','Synthetische Originalreferenz',fx_u,'Synthetic Wound Documenter');
  SELECT to_jsonb(o) INTO fx_order_before FROM public.care_medical_orders o WHERE o.id=fx_order;
  fx_plan_data:=jsonb_build_object('expectedPreviousId','','effectiveFrom',to_char((fx_base+interval '2 minutes 0.123456 seconds') at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'effectiveUntil',to_char((fx_base+interval '1 day') at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'basisState','linked','medicalOrderId',fx_order,'expectedOrderJson',fx_order_before::text,'basisReason','Synthetischen vollständigen Anordnungsstand ausdrücklich zuordnen','professionalBasis','Synthetische fachliche Planbegründung','changeReason','Erste isolierte synthetische Planfassung','goal','Individuelles synthetisches Testziel','plannedCare','Nur fiktive geplante Handlung','plannedMaterials','Synthetisch geplante Materialangabe','frequency','Nur synthetisch ausdrücklich festgelegte Häufigkeit','hygienePlan','Synthetische geplante Hygienebeschreibung','painPlan','Synthetischer Umgang mit nicht erhobenem Schmerz','warningSigns','Synthetisch ausdrücklich benannte Beobachtungszeichen','escalationPath','Synthetischer nächster Kontaktweg','personDecision','Fiktive persönliche Entscheidung dokumentiert','reviewStatus','pending','nextReviewAt','','reviewPendingReason','Synthetischer Kontrolltermin noch offen');
  fx_plan_payload:=jsonb_build_object('action','plan','woundId',fx_wound,'dataJson',fx_plan_data::text);
  BEGIN UPDATE public.care_medical_orders SET description='Changed original order' WHERE id=fx_order;PERFORM care_private.write_wound_care(gen_random_uuid(),fx_plan_payload);RAISE EXCEPTION 'Stale complete medical order accepted';EXCEPTION WHEN serialization_failure THEN NULL;END;
  fx_plan:=care_private.write_wound_care(fx_plan_req,fx_plan_payload);
  IF care_private.write_wound_care(fx_plan_req,fx_plan_payload) IS DISTINCT FROM fx_plan THEN RAISE EXCEPTION 'Plan retry changed result';END IF;
  BEGIN PERFORM care_private.write_wound_care(gen_random_uuid(),fx_plan_payload);RAISE EXCEPTION 'Stale previous plan accepted';EXCEPTION WHEN serialization_failure THEN NULL;END;

  fx_dress_data:=jsonb_build_object('occurredAt',to_char((fx_base+interval '3 minutes 0.234567 seconds') at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'outcome','omitted','basisState','linked','planId',fx_plan,'basisReason','','actualCleaning','Im synthetischen Test nicht durchgeführt','actualTechnique','Im synthetischen Test nicht durchgeführt','hygiene','Keine tatsächliche Maßnahme im isolierten Test','materialsJson','[]','noMaterialReason','Kein Verbrauch bei fiktiver Nichtdurchführung','painBeforeState','not_assessable','painBeforeScore','','painBeforeReason','Im Test vorab nicht erhoben','painAfterState','not_assessable','painAfterScore','','painAfterReason','Im Test anschließend nicht erhoben','response','Synthetische Nichtdurchführung dokumentiert','deviation','Synthetisch begründete Nichtdurchführung','contact','Synthetischer Klärungsbedarf dokumentiert','personDecision','Fiktive persönliche Entscheidung einbezogen','qualificationBasis','Keine Qualifikationsfreigabe; synthetische Nichtdurchführungsdokumentation','reviewStatus','pending','nextReviewAt','','reviewPendingReason','Synthetische Kontrolle noch abzustimmen');
  fx_dress_payload:=jsonb_build_object('action','dressing','woundId',fx_wound,'dataJson',fx_dress_data::text);
  fx_dressing:=care_private.write_wound_care(fx_dress_req,fx_dress_payload);
  IF care_private.write_wound_care(fx_dress_req,fx_dress_payload) IS DISTINCT FROM fx_dressing OR NOT EXISTS(SELECT 1 FROM public.ambulatory_wound_dressings d JOIN public.clinical_treatment_executions e ON e.id=d.execution_id WHERE d.id=fx_dressing AND d.plan_id=fx_plan AND d.outcome='omitted' AND e.outcome='omitted') THEN RAISE EXCEPTION 'Actual nonperformance original or replay missing';END IF;
  IF (SELECT to_jsonb(o) FROM public.care_medical_orders o WHERE o.id=fx_order) IS DISTINCT FROM fx_order_before THEN RAISE EXCEPTION 'Documentation changed order or payer approval';END IF;

  fx_context:=care_private.read_wound_path_context_impl(fx_t,fx_c,fx_wound,fx_u);
  IF jsonb_array_length(fx_context->'wounds') IS DISTINCT FROM 1 OR jsonb_array_length(fx_context->'assessments') IS DISTINCT FROM 1 OR jsonb_array_length(fx_context->'plans') IS DISTINCT FROM 1 OR jsonb_array_length(fx_context->'dressings') IS DISTINCT FROM 1 OR fx_context#>'{assessments,0,payload,pain_score}' IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION 'Complete native wound context invented or omitted originals';END IF;
  fx_entry:=jsonb_build_object('kind','infection_suspicion','title','Synthetische Wundbeobachtung ohne automatische Diagnose','tenantId',fx_t,'clientId',fx_c,'woundId',fx_wound,'observedAt',to_char((fx_base+interval '4 minutes 0.345678 seconds') at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
   'observation',jsonb_build_object('state','suspected','signs',jsonb_build_array('Synthetisch beobachtete Rötung'),'narrative','Nur fiktive Beobachtung, keine Diagnose','assessmentId',fx_assessment,'photoId',null,'photoConsentId',null),
   'contact',jsonb_build_object('state','pending','channel','','contactedAt',null,'contactName','','responseAt',null,'response','','nextStep','Synthetischen Kontaktweg klären','responsibleBy',null),
   'care',jsonb_build_object('planId',null,'dressingId',null,'outcome','none','occurredAt',null,'action','','reason','Keine zusätzliche Versorgung aus Beobachtung ableiten'),
   'person',jsonb_build_object('decision','Fiktive persönliche Entscheidung ausdrücklich dokumentiert','informedAt',null,'photoDecision','not_applicable'),
   'resolution',jsonb_build_object('state','open','resolvedAt',null,'result','','followUpAt',null,'responsibleBy',null),
   'correction',jsonb_build_object('targetId',null,'reason','','replacementId',null,'approvedBy',null,'approvedAt',null));
  fx_packet:=jsonb_build_object('schemaVersion','1','action','create','requestId',fx_path_req,'tenantId',fx_t,'clientId',fx_c,'woundId',fx_wound,'actorId',fx_u,'expectedHeadId',null,'expectedRevision',0,'entry',fx_entry,'reason','','original',null,'sources',fx_context);
  fx_receipt:=care_private.commit_wound_path_packet_impl(fx_packet);
  IF fx_receipt#>>'{original,revision}' IS DISTINCT FROM '1' OR fx_receipt#>>'{original,payload,care,outcome}' IS DISTINCT FROM 'none' OR (fx_receipt#>>'{original,recordedAt}')::timestamptz IS DISTINCT FROM (fx_entry->>'observedAt')::timestamptz THEN RAISE EXCEPTION 'Original path or microsecond time differs';END IF;
  IF care_private.confirm_wound_path_packet_impl(fx_t,fx_c,fx_wound,fx_u,fx_path_req,fx_packet) IS DISTINCT FROM fx_receipt THEN RAISE EXCEPTION 'Own initial path confirmation differs';END IF;
  BEGIN PERFORM care_private.commit_wound_path_packet_impl(jsonb_set(fx_packet,'{requestId}',to_jsonb(gen_random_uuid())));RAISE EXCEPTION 'Stale source collection accepted';EXCEPTION WHEN serialization_failure THEN NULL;END;
  BEGIN PERFORM care_private.commit_wound_path_packet_impl(jsonb_set(fx_packet,'{entry,observation,narrative}','"Other original payload"'));RAISE EXCEPTION 'Path request ID reused for changed facts';EXCEPTION WHEN check_violation THEN NULL;END;

  fx_context:=care_private.read_wound_path_context_impl(fx_t,fx_c,fx_wound,fx_u);
  fx_closed_entry:=fx_entry||jsonb_build_object('kind','escalation_resolution','title','Synthetisch dokumentierter Abschluss des Kontaktwegs','observedAt',to_char((fx_base+interval '6 minutes 0.456789 seconds') at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
   'contact',jsonb_build_object('state','responded','channel','Synthetischer Telefonkontakt','contactedAt',to_char((fx_base+interval '4 minutes') at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'contactName','Fiktive Testpraxis','responseAt',to_char((fx_base+interval '5 minutes') at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'response','Fiktive tatsächliche Rückmeldung im isolierten Test','nextStep','Synthetisch vorgesehenen Kontrollbedarf weitergeben','responsibleBy',fx_u),
   'care',jsonb_build_object('planId',fx_plan,'dressingId',fx_dressing,'outcome','omitted','occurredAt',fx_context#>'{dressings,0,payload,occurred_at}','action','Synthetische Nichtdurchführung aus Originalbeleg','reason',fx_dress_data->>'deviation'),
   'resolution',jsonb_build_object('state','resolved','resolvedAt',to_char((fx_base+interval '6 minutes') at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'result','Fiktiver Kontaktabschluss ohne klinische Freigabe','followUpAt',null,'responsibleBy',fx_u));
  fx_packet2:=fx_packet||jsonb_build_object('action','revise','requestId',fx_revise_req,'expectedHeadId',fx_path_req,'expectedRevision',1,'entry',fx_closed_entry,'reason','Tatsächliche synthetische Rückmeldung und Nichtdurchführung fortschreiben','original',fx_receipt->'original','sources',fx_context);
  BEGIN PERFORM care_private.commit_wound_path_packet_impl(jsonb_set(fx_packet2,'{entry,care,outcome}','"performed"'));RAISE EXCEPTION 'Nonperformance source changed to performed';EXCEPTION WHEN check_violation THEN NULL;END;
  fx_bad:=jsonb_set(fx_packet2,'{entry,care,occurredAt}',to_jsonb(to_char(((fx_dress_data->>'occurredAt')::timestamptz+interval '0.000001 seconds') at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')));
  BEGIN PERFORM care_private.commit_wound_path_packet_impl(fx_bad);RAISE EXCEPTION 'One-microsecond actual-time substitution accepted';EXCEPTION WHEN check_violation THEN NULL;END;
  BEGIN PERFORM care_private.commit_wound_path_packet_impl(jsonb_set(fx_packet2,'{actorId}',to_jsonb(fx_reviewer)));RAISE EXCEPTION 'Foreign current actor accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  fx_receipt2:=care_private.commit_wound_path_packet_impl(fx_packet2);
  IF fx_receipt2#>>'{original,revision}' IS DISTINCT FROM '2' OR jsonb_array_length(fx_receipt2#>'{original,history}') IS DISTINCT FROM 2 OR fx_receipt2#>>'{original,payload,care,outcome}' IS DISTINCT FROM 'omitted' THEN RAISE EXCEPTION 'Complete source-linked path history missing';END IF;
  IF care_private.commit_wound_path_packet_impl(fx_packet) IS DISTINCT FROM fx_receipt OR care_private.confirm_wound_path_packet_impl(fx_t,fx_c,fx_wound,fx_u,fx_path_req,fx_packet) IS DISTINCT FROM fx_receipt THEN RAISE EXCEPTION 'Historical request replay returned later path head';END IF;
  BEGIN PERFORM care_private.commit_wound_path_packet_impl(fx_packet2||jsonb_build_object('requestId',gen_random_uuid()));RAISE EXCEPTION 'Stale original path head accepted';EXCEPTION WHEN serialization_failure THEN NULL;END;

  fx_review_packet:=jsonb_build_object('schemaVersion','1','action','request','requestId',fx_review_req,'tenantId',fx_t,'clientId',fx_c,'woundId',fx_wound,'actorId',fx_u,'expectedHeadId',null,'expectedRevision',0,'woundOriginal',fx_receipt2->'original','sources',care_private.read_wound_path_context_impl(fx_t,fx_c,fx_wound,fx_u),'reviewOriginal',null,'reason','Getrennte Prüfung der vollständigen synthetischen Wundfassung','requiredChange','','rationale','');
  fx_review_receipt:=care_private.commit_wound_path_review(fx_review_packet);
  IF fx_review_receipt#>>'{original,rootId}' IS DISTINCT FROM fx_review_receipt#>>'{original,history,0,id}' OR fx_review_receipt#>>'{original,headId}' IS DISTINCT FROM fx_review_receipt#>>'{original,rootId}' OR fx_review_receipt#>>'{original,status}' IS DISTINCT FROM 'requested' OR fx_review_receipt#>'{original,history,0,qualification}' IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION 'Review request invented qualification or acceptance';END IF;
  IF care_private.confirm_wound_path_review(fx_t,fx_c,fx_wound,fx_u,fx_review_req,fx_review_packet) IS DISTINCT FROM fx_review_receipt THEN RAISE EXCEPTION 'Own technical review request not independently confirmed';END IF;
  fx_decision_packet:=fx_review_packet||jsonb_build_object('action','accept','requestId',fx_decision_req,'expectedHeadId',fx_review_receipt#>'{original,headId}','expectedRevision',1,'reviewOriginal',fx_review_receipt->'original','reason','','rationale','Nur synthetischen Qualifikations- und Originalvertrag technisch prüfen');
  BEGIN PERFORM care_private.commit_wound_path_review(fx_decision_packet);RAISE EXCEPTION 'Requesting documenter accepted its own clinical review';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
  PERFORM set_config('request.jwt.claims',fx_review_claims::text,true);
  fx_decision_packet:=fx_decision_packet||jsonb_build_object('actorId',fx_reviewer,'sources',care_private.read_wound_path_context_impl(fx_t,fx_c,fx_wound,fx_reviewer));
  BEGIN PERFORM care_private.commit_wound_path_review(fx_decision_packet);RAISE EXCEPTION 'Role alone invented verified employment and qualification';EXCEPTION WHEN insufficient_privilege THEN NULL;END;

  -- Privileged synthetic qualification fixture. No real person, certificate, license or clinical clearance is created.
  INSERT INTO public.employees(id,tenant_id,profile_id,first_name,last_name,status,start_date,entry_date) VALUES(fx_employee,fx_t,fx_reviewer,'Synthetic','Reviewer','aktiv',(fx_base at time zone 'Europe/Berlin')::date-30,(fx_base at time zone 'Europe/Berlin')::date-30);
  INSERT INTO public.employee_employment_details(tenant_id,employee_id,employment_status) VALUES(fx_t,fx_employee,'active');
  INSERT INTO public.employee_documents(id,tenant_id,employee_id,category,title,file_name,storage_path,sensitive,released_to_portal,valid_until) VALUES(fx_document,fx_t,fx_employee,'synthetic_fixture','Synthetic credential fixture','synthetic-fixture.txt','synthetic-fixtures/'||fx_t||'/qualification.txt',true,false,(fx_base at time zone 'Europe/Berlin')::date+30);
  INSERT INTO public.employee_qualifications(id,tenant_id,employee_id,qualification_type,title,issued_at,valid_until,document_id,verified_by,verified_at,status) VALUES(fx_qualification,fx_t,fx_employee,'synthetic_fixture','Synthetic credential contract only',(fx_base at time zone 'Europe/Berlin')::date-20,(fx_base at time zone 'Europe/Berlin')::date+30,fx_document,'Synthetic test authority',fx_base,'valid');
  INSERT INTO care_private.wound_path_review_scopes(id,tenant_id,employee_id,qualification_id,kind,qualification_fingerprint,document_fingerprint,approved_by,approved_at,valid_until)
  SELECT fx_scope,fx_t,fx_employee,fx_qualification,'wound_care_review',care_private.wound_path_fingerprint(to_jsonb(q)),care_private.wound_path_fingerprint(to_jsonb(d)),fx_u,fx_base,clock_timestamp()+interval '1 hour' FROM public.employee_qualifications q JOIN public.employee_documents d ON d.id=q.document_id WHERE q.id=fx_qualification;
  fx_decision_packet:=fx_decision_packet||jsonb_build_object('sources',care_private.read_wound_path_context_impl(fx_t,fx_c,fx_wound,fx_reviewer));
  BEGIN UPDATE care_private.wound_path_review_scopes SET revoked_at=clock_timestamp() WHERE id=fx_scope;PERFORM care_private.commit_wound_path_review(fx_decision_packet);RAISE EXCEPTION 'Revoked private qualification scope accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
